fixed_height_rules:
/* ==========================================================================
       CYBERPUNK DESIGN SYSTEM & CSS VARIABLES
       ========================================================================== */
    :root { --bg-base: #030812; --bg-surface: #060d1b; --bg-card: #081224; --bg-card-hover: #0d1c38; --bg-elevated: #0f2244; --border-subtle: rgba(6, 182, 212, 0.15); --border-accent: rgba(6, 182, 212, 0.35); --border-glow: rgba(6, 182, 212, 0.6); --cyan-primary: #06b6d4; --cyan-glow: #22d3ee; --cyan-dim: rgba(6, 182, 212, 0.12); --blue-accent: #3b82f6; --blue-glow: #60a5fa; --emerald-ok: #10b981; --emerald-glow: #34d399; --emerald-dim: rgba(16, 185, 129, 0.15); --amber-warn: #f59e0b; --amber-glow: #fbbf24; --amber-dim: rgba(245, 158, 11, 0.15); --crimson-crit: #ef4444; --crimson-glow: #f87171; --crimson-dim: rgba(239, 68, 68, 0.15); --purple-heal: #8b5cf6; --purple-glow: #a78bfa; --purple-dim: rgba(139, 92, 246, 0.15); --text-main: #f1f5f9; --text-muted: #94a3b8; --text-dim: #64748b; --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; --font-mono: 'JetBrains Mono', 'Cascadia Code', 'Fira Code', 'SF Mono', Consolas, monospace; --header-height: 72px; --terminal-height: 240px; --radius-sm: 4px; --radius-md: 8px; --radius-lg: 12px; --radius-full: 9999px; --transition-fast: 0.15s ease; --transition-normal: 0.25s ease; --transition-slow: 0.4s cubic-bezier(0.16, 1, 0.3, 1); }

z_index_rules:
/* ==========================================================================
       HEADER & NAVIGATION
       ========================================================================== */
    .noc-header { height: var(--header-height); background: rgba(6, 13, 27, 0.85); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); border-bottom: 1px solid var(--border-subtle); position: sticky; top: 0; z-index: 100; display: flex; align-items: center; justify-content: space-between; padding: 0 2rem; gap: 1.5rem; }

/* ==========================================================================
       CHAOS CONTROL MODAL & 5-STEP AUTO-HEALING WORKFLOW
       ========================================================================== */
    .chaos-overlay { position: fixed; inset: 0; background: rgba(3, 8, 18, 0.8); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); z-index: 200; display: flex; align-items: center; justify-content: center; padding: 1.5rem; opacity: 0; pointer-events: none; transition: opacity var(--transition-normal); }

/* ==========================================================================
       ANSI LIVE STREAMING TERMINAL CONSOLE (COLLAPSIBLE DRAWER)
       ========================================================================== */
    .terminal-drawer { position: fixed; bottom: 0; left: 0; right: 0; height: var(--terminal-height); background: rgba(3, 8, 18, 0.96); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); border-top: 1px solid var(--border-subtle); z-index: 150; display: flex; flex-direction: column; box-shadow: 0 -8px 32px rgba(0, 0, 0, 0.7); transition: height var(--transition-normal), transform var(--transition-normal); }

/* ==========================================================================
       CYBERPUNK 90-DAY SLA TOOLTIP
       ========================================================================== */
    .sla-tooltip { position: fixed; z-index: 300; background: linear-gradient(180deg, #0b172d 0%, #060d1b 100%); border: 1px solid var(--border-accent); border-radius: var(--radius-md); padding: 0.75rem 1rem; box-shadow: 0 8px 30px rgba(0, 0, 0, 0.8), 0 0 15px var(--cyan-dim); pointer-events: none; opacity: 0; transform: translateY(6px); transition: opacity 0.15s ease, transform 0.15s ease; max-width: 280px; font-size: 0.75rem; display: flex; flex-direction: column; gap: 0.4rem; }

/* ==========================================================================
       TOAST NOTIFICATIONS
       ========================================================================== */
    .toast-container { position: fixed; top: calc(var(--header-height) + 16px); right: 24px; z-index: 250; display: flex; flex-direction: column; gap: 0.75rem; pointer-events: none; }

/* ==========================================================================
       BIFURCATION BRANCHES CONTAINER (Node 3B & Node 4B)
       ========================================================================== */
    .bifurcations-container { margin-top: 36px; display: grid; grid-template-columns: repeat(6, 1fr); gap: 16px; position: relative; z-index: 2; }

/* ==========================================================================
       HEADER & MISSION CONTROL BAR
       ========================================================================== */
    .app-header { background: var(--bg-header); backdrop-filter: blur(16px); -webkit-backdrop-filter: blur(16px); border: 1px solid var(--border-subtle); border-radius: var(--radius-lg); padding: 14px 22px; display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 16px; box-shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.6), 0 0 15px -3px var(--amber-glow); position: sticky; top: 12px; z-index: 100; }

/* ==========================================================================
       DLQ INSPECTOR & PAYLOAD MODAL
       ========================================================================== */
    .modal-overlay { position: fixed; inset: 0; background: rgba(3, 8, 18, 0.85); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); display: flex; align-items: center; justify-content: center; z-index: 1000; opacity: 0; pointer-events: none; transition: opacity 0.2s ease; padding: 20px; }
